<style>.color-alert{margin-bottom:18px;padding:12px 15px;color:#365844;background:#e8f1e6;border:1px solid #d5e6d2;border-radius:9px;font-size:12px}.color-layout{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:17px;align-items:start}.color-panel{overflow:hidden}.color-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px;padding:0 20px 20px}.color-field{display:grid;gap:7px;color:#59665b;font-size:11px;font-weight:700}.color-field>div{display:flex;gap:8px}.color-picker{width:43px;height:40px;flex:0 0 43px;padding:3px;background:#fff;border:1px solid #e1e5dc;border-radius:8px;cursor:pointer}.color-hex{min-width:0;flex:1;padding:9px 10px;border:1px solid #e1e5dc;border-radius:8px;font:inherit;font-size:12px;text-transform:uppercase}.color-field small{color:#a34d40;font-size:9px}.color-actions{padding:0 20px 20px}.color-save{min-height:41px;padding:0 15px;color:#fff;background:var(--green-dark);border:0;border-radius:8px;cursor:pointer;font-size:11px;font-weight:700}.preview-panel{padding:18px;background:#fffefa;border:1px solid var(--line);border-radius:12px;box-shadow:var(--shadow)}.preview-heading{display:flex;gap:10px;align-items:center;margin-bottom:15px}.preview-heading>i{width:34px;height:34px;display:grid;place-items:center;color:#5e8061;background:#edf4e9;border-radius:9px}.preview-heading strong{display:block;font-size:12px}.preview-heading span{display:block;margin-top:3px;color:#9ba39a;font-size:9px}.preview-shell{height:224px;display:flex;overflow:hidden;border:1px solid #dce4d9;border-radius:9px;--pv-primary:#54745d;--pv-bg:#f7f6f1;--pv-text:#26382f;--pv-accent:#bd795e;--pv-sidebar:#fff;--pv-panel:#fffefa}.preview-sidebar{width:58px;display:grid;align-content:start;gap:12px;padding:12px 10px;background:var(--pv-sidebar)}.preview-sidebar span:not(.preview-mark){height:5px;background:var(--pv-primary);border-radius:3px;opacity:.55}.preview-mark{height:28px;display:grid;place-items:center;color:#fff;background:var(--pv-primary);border-radius:7px;font-size:10px}.preview-content{flex:1;padding:13px;background:var(--pv-bg)}.preview-top{display:flex;justify-content:space-between;color:var(--pv-text);font-size:9px}.preview-top i{width:22px;height:8px;background:var(--pv-accent);border-radius:9px}.preview-banner{display:grid;gap:11px;margin-top:13px;padding:13px;color:#fff;background:var(--pv-primary);border-radius:8px;font-size:11px}.preview-banner span{width:55%;height:5px;background:rgba(255,255,255,.55);border-radius:3px}.preview-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin-top:10px}.preview-cards i{height:34px;background:var(--pv-panel);border:1px solid rgba(0,0,0,.05);border-radius:6px}.preview-lines{display:grid;gap:7px;margin-top:10px;padding:10px;background:var(--pv-panel);border-radius:6px}.preview-lines i{height:4px;background:var(--pv-text);border-radius:3px;opacity:.3}.preview-lines i:nth-child(2){width:80%}.preview-lines i:nth-child(3){width:62%}.color-reset{width:100%;min-height:39px;margin-top:13px;color:#687968;background:#f5f7f3;border:1px solid #e1e8de;border-radius:7px;cursor:pointer;font-size:10px;font-weight:700}@media(max-width:900px){.color-layout{grid-template-columns:1fr}.preview-panel{max-width:600px}}@media(max-width:520px){.color-fields{grid-template-columns:1fr;padding-right:14px;padding-left:14px}.color-actions{padding-right:14px;padding-left:14px}}</style>
<script>(()=>{const preview=document.getElementById('themePreview');const keys={primary_color:'--pv-primary',background_color:'--pv-bg',text_color:'--pv-text',accent_color:'--pv-accent',sidebar_color:'--pv-sidebar',panel_color:'--pv-panel'};document.querySelectorAll('.color-picker').forEach(picker=>{const input=document.getElementById(picker.dataset.target);const apply=value=>{if(/^#[0-9a-f]{6}$/i.test(value)){preview.style.setProperty(keys[picker.dataset.target],value);picker.value=value;}};picker.addEventListener('input',()=>{input.value=picker.value;apply(picker.value)});input.addEventListener('input',()=>apply(input.value));apply(input.value);});})();</script>
